mapper.select:
SELECT , p.name AS product_name
FROM t_invest_order o
LEFT JOIN t_product p ON p.id = o.product_id
WHERE o.user_id = #{userId}
ORDER BY o.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT , p.name AS product_name, u.username FROM t_invest_order o LEFT JOIN t_product p ON p.id = o.product_id LEFT JOIN t_user u ON u.id = o.user_id
AND o.status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM t_invest_order o LEFT JOIN t_product p ON p.id = o.product_id LEFT JOIN t_user u ON u.id = o.user_id
AND o.status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
